// Ported from the Node app's Sequelize model InventoryItem (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class InventoryItemConfiguration : IEntityTypeConfiguration<InventoryItem>
{
    public void Configure(EntityTypeBuilder<InventoryItem> builder)
    {
        builder.ToTable("inventory_items");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.Property(e => e.CategoryId).HasColumnName("category_id");
        builder.Property(e => e.Unit).HasColumnName("unit").HasColumnType("nvarchar(20)").HasMaxLength(20).IsRequired().HasDefaultValueSql("N'pcs'");
        builder.Property(e => e.ReorderLevel).HasColumnName("reorder_level").HasDefaultValueSql("0");
        builder.Property(e => e.Quantity).HasColumnName("quantity").HasDefaultValueSql("0");
        builder.HasIndex(e => e.Name).IsUnique();
        builder.HasOne(e => e.InventoryCategory).WithMany(p => p.InventoryItems).HasForeignKey(e => e.CategoryId).OnDelete(DeleteBehavior.NoAction);
    }
}
